CREATE TABLE challenges(id BIGSERIAL PRIMARY KEY,code VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,description VARCHAR(255) NOT NULL,type VARCHAR(40) NOT NULL,target_value INTEGER NOT NULL,xp_reward BIGINT NOT NULL,active BOOLEAN NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_challenges(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),challenge_id BIGINT NOT NULL REFERENCES challenges(id),progress INTEGER NOT NULL DEFAULT 0,completed BOOLEAN NOT NULL DEFAULT FALSE,completed_at TIMESTAMP WITH TIME ZONE,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT user_challenges_unique UNIQUE(user_id,challenge_id));
